import React, { useState, useEffect } from "react";
import styled from "styled-components";
import { Container, Row, Col, Button, Form } from "react-bootstrap";
import { Download, ArrowRepeat } from "react-bootstrap-icons";
import JSZip from "jszip";
import { saveAs } from "file-saver";
import "react-toastify/dist/ReactToastify.css";
import { ToastContainer, toast } from "react-toastify";

const HeaderSection = styled.div`
  background-color: #343a40;
  color: #f8f9fa;
  padding: 2rem 1rem;
  text-align: center;
`;

function App() {
  useEffect(() => {
    document.cookie = "yourCookieName=yourCookieValue; SameSite=None; Secure";
    // AD: 구글 애드센스 스크립트가 중복 로딩되지 않도록 체크
    if (!window.adsbygoogle) {
      const adsbygoogleScript = document.createElement("script");
      adsbygoogleScript.src =
        "https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js";
      adsbygoogleScript.async = true;
      adsbygoogleScript.crossOrigin = "anonymous";
      document.head.appendChild(adsbygoogleScript);
    }

    // 이미 adsbygoogle이 로드된 경우 광고를 다시 푸시하지 않음
    const adsbygoogle = window.adsbygoogle || [];
    if (adsbygoogle.length === 0) {
      adsbygoogle.push({});
    }
  }, []);

  // useState
  const [files, setFiles] = useState([]);
  const [webpUrls, setWebpUrls] = useState([]);
  const [, setConversionStatus] = useState([]);
  const [imageInfos, setImageInfos] = useState([]);
  const [webpImageInfos, setWebpImageInfos] = useState([]);
  const [resizeOptions, setResizeOptions] = useState([]);
  const [conversionProgress, setConversionProgress] = useState(0); // 0~100%
  const [isConverting, setIsConverting] = useState(false);

  const handleFileChange = (event) => {
    const selectedFilesArray = Array.from(event.target.files);
    setFiles(selectedFilesArray);
    setWebpUrls([]);
    setConversionStatus(selectedFilesArray.map(() => ""));

    // 이미지 정보 저장
    const infos = [];
    selectedFilesArray.forEach((file) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        const img = new Image();
        img.src = e.target.result;
        img.onload = () => {
          infos.push({
            previewUrl: e.target.result,
            width: img.width,
            height: img.height,
            size: file.size,
          });

          if (infos.length === selectedFilesArray.length) {
            setImageInfos(infos);

            const initialResizeOptions = infos.map((info) => [
              {
                width: info.width,
                height: info.height,
                maintainRatio: true,
              },
            ]);
            setResizeOptions(initialResizeOptions);
          }
        };
      };
      reader.readAsDataURL(file);
    });
  };

  const convertToWebp = (file, index, optionsList) => {
    const reader = new FileReader();

    reader.onload = (event) => {
      const img = new Image();
      img.src = event.target.result;

      img.onload = () => {
        if (!optionsList || optionsList.length === 0) {
          optionsList = [
            {
              width: img.width,
              height: img.height,
              maintainRatio: true,
            },
          ];
        }

        optionsList.forEach((option, subIndex) => {
          const canvas = document.createElement("canvas");
          const ctx = canvas.getContext("2d");

          let targetWidth = img.width;
          let targetHeight = img.height;

          if (option.width) {
            targetWidth = option.width;
            if (option.maintainRatio && img.width > 0) {
              targetHeight = Math.round((img.height / img.width) * targetWidth);
            }
          }
          if (option.height && !option.maintainRatio) {
            targetHeight = option.height;
          }

          canvas.width = targetWidth;
          canvas.height = targetHeight;
          ctx.drawImage(img, 0, 0, targetWidth, targetHeight);

          canvas.toBlob(
            (blob) => {
              if (blob) {
                const webpUrl = URL.createObjectURL(blob);

                setWebpUrls((prev) => {
                  const updated = [...prev];
                  if (!updated[index]) updated[index] = [];
                  updated[index][subIndex] = webpUrl;
                  return updated;
                });

                setWebpImageInfos((prev) => {
                  const updated = [...prev];
                  if (!updated[index]) updated[index] = [];
                  updated[index][subIndex] = { size: blob.size };
                  return updated;
                });
              }
            },
            "image/webp",
            { quality: 1 }
          );
        });
      };
    };

    reader.readAsDataURL(file);
  };
  

  const handleConvert = (index) => {
    const options = resizeOptions[index];
    const fileName = files[index]?.name || `Image #${index + 1}`;
    const { isValid, validOptions, messages, firstInvalidInputId } =
      getValidatedResizeOptions(options, index, fileName);

    if (!isValid) {
      messages.forEach((msg) => toast.error(msg));
      if (firstInvalidInputId) {
        setTimeout(() => {
          const el = document.getElementById(firstInvalidInputId);
          if (el) el.focus();
        }, 100);
      }
      return;
    }

    const updated = [...resizeOptions];
    updated[index] = validOptions;
    setResizeOptions(updated);

    convertToWebp(files[index], index, validOptions);
  };


  const handleConvertAll = async () => {
    let totalTasks = 0;
    let allValid = true;
    const updatedResizeOptions = [...resizeOptions];
    const allMessages = [];
    let firstInvalidInputId = null;

    // 1. 유효성 검사 먼저 수행
    for (let index = 0; index < files.length; index++) {
      const options = resizeOptions[index] || [];
      const fileName = files[index]?.name || `Image #${index + 1}`;
      const { isValid, validOptions, messages, firstInvalidInput } =
        getValidatedResizeOptions(options, index, fileName);

      updatedResizeOptions[index] = validOptions;

      if (!isValid) {
        allValid = false;
        allMessages.push(...messages);
        if (!firstInvalidInputId && firstInvalidInput) {
          firstInvalidInputId = firstInvalidInput;
        }
      } else {
        totalTasks += validOptions.length;
      }
    }

    // 2. 유효하지 않으면 경고 메시지 출력 후 중단
    if (!allValid) {
      setResizeOptions(updatedResizeOptions);
      allMessages.forEach((msg) => toast.error(msg));
      if (firstInvalidInputId) {
        setTimeout(() => {
          const el = document.getElementById(firstInvalidInputId);
          if (el) el.focus();
        }, 100);
      }
      return;
    }

    // 3. 변환 진행
    setResizeOptions(updatedResizeOptions);
    let completed = 0;
    setIsConverting(true);
    setConversionProgress(0);

    for (let index = 0; index < files.length; index++) {
      const file = files[index];
      const options = updatedResizeOptions[index] || [];

      for (let subIndex = 0; subIndex < options.length; subIndex++) {
        await convertToWebpWithCallback(file, index, subIndex);
        completed++;
        setConversionProgress(Math.round((completed / totalTasks) * 100));
      }
    }

    setIsConverting(false);
  };
  
  
  const convertToWebpWithCallback = (file, index, subIndex) => {
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.src = event.target.result;
        img.onload = () => {
          const canvas = document.createElement("canvas");
          const ctx = canvas.getContext("2d");

          const option = resizeOptions[index]?.[subIndex] || {
            width: img.width,
            height: img.height,
            maintainRatio: true,
          };

          let targetWidth = option.width || img.width;
          let targetHeight = option.maintainRatio
            ? Math.round((img.height / img.width) * targetWidth)
            : option.height || img.height;

          canvas.width = targetWidth;
          canvas.height = targetHeight;
          ctx.drawImage(img, 0, 0, targetWidth, targetHeight);

          canvas.toBlob(
            (blob) => {
              const webpUrl = URL.createObjectURL(blob);
              setWebpUrls((prev) => {
                const updated = [...prev];
                if (!updated[index]) updated[index] = [];
                updated[index][subIndex] = webpUrl;
                return updated;
              });
              resolve();
            },
            "image/webp",
            { quality: 1 }
          );
        };
      };
      reader.readAsDataURL(file);
    });
  };
  
  const handleResizeInputChange = (fileIndex, optionIndex, field, value) => {
    setResizeOptions((prev) => {
      const updated = [...prev];
      if (!updated[fileIndex]) updated[fileIndex] = [];
      if (!updated[fileIndex][optionIndex])
        updated[fileIndex][optionIndex] = {};
      updated[fileIndex][optionIndex][field] =
        field === "maintainRatio" ? value : parseInt(value);
      return updated;
    });
  };

  const allConverted =
    webpUrls.length > 0 && webpUrls.every((url) => url !== undefined);

  const handleDownloadAll = async () => {
    const zip = new JSZip();

    for (let fileIndex = 0; fileIndex < webpUrls.length; fileIndex++) {
      const urlList = webpUrls[fileIndex];
      if (!urlList) continue;

      for (let subIndex = 0; subIndex < urlList.length; subIndex++) {
        const url = urlList[subIndex];
        if (!url) continue;

        const response = await fetch(url);
        const blob = await response.blob();

        const name = files[fileIndex].name.split(".").slice(0, -1).join(".");
        const width = resizeOptions[fileIndex]?.[subIndex]?.width || "auto";
        const height = resizeOptions[fileIndex]?.[subIndex]?.height || "auto";
        const filename = `${name}-${width}x${height}.webp`;

        zip.file(filename, blob);
      }
    }

    zip.generateAsync({ type: "blob" }).then((zipBlob) => {
      saveAs(zipBlob, "converted-images.zip");
    });
  };

  const handleAddResizeOption = (fileIndex) => {
    setResizeOptions((prev) => {
      const updated = [...prev];
      const currentList = updated[fileIndex] ? [...updated[fileIndex]] : [];

      currentList.push({
        width: "",
        height: "",
        maintainRatio: true,
      });

      updated[fileIndex] = currentList;
      return updated;
    });
  };
  

  const handleRemoveResizeOption = (fileIndex, optionIndex) => {
    setResizeOptions((prev) => {
      const updated = [...prev];
      updated[fileIndex] = updated[fileIndex].filter(
        (_, i) => i !== optionIndex
      );
      return updated;
    });
  };

  const handleDownloadOne = async (fileIndex) => {
    const zip = new JSZip();
    const urlList = webpUrls[fileIndex];

    if (!urlList) return;

    for (let subIndex = 0; subIndex < urlList.length; subIndex++) {
      const url = urlList[subIndex];
      if (!url) continue;

      const response = await fetch(url);
      const blob = await response.blob();

      const name = files[fileIndex].name.split(".").slice(0, -1).join(".");
      const width = resizeOptions[fileIndex]?.[subIndex]?.width || "auto";
      const height = resizeOptions[fileIndex]?.[subIndex]?.height || "auto";
      const filename = `${name}-${width}x${height}.webp`;

      zip.file(filename, blob);
    }

    zip.generateAsync({ type: "blob" }).then((zipBlob) => {
      saveAs(zipBlob, `${files[fileIndex].name.split(".")[0]}-converted.zip`);
    });
  };

  const getValidatedResizeOptions = (
    options,
    fileIndex = null,
    fileName = ""
  ) => {
    let isValid = true;
    const validOptions = [];
    const messages = [];
    let firstInvalidInputId = null;

    options.forEach((opt, optIndex) => {
      const widthEmpty = !opt.width;
      const heightEmpty = !opt.height;
      const maintainRatio = opt.maintainRatio;

      if (widthEmpty && heightEmpty) {
        return; 
      }

      const invalid =
        (!maintainRatio && (widthEmpty || heightEmpty)) ||
        (maintainRatio && widthEmpty);

      if (invalid) {
        isValid = false;
        const prefix = fileName
          ? `${fileName} (Option #${optIndex + 1}): `
          : `Option #${optIndex + 1}: `;

        const msg = maintainRatio
          ? "Please enter Width (Maintain Ratio enabled)"
          : "Width or Height is missing.";

        messages.push(prefix + msg);

        if (!firstInvalidInputId) {
          firstInvalidInputId = maintainRatio
            ? `resize-width-${fileIndex}-${optIndex}`
            : widthEmpty
            ? `resize-width-${fileIndex}-${optIndex}`
            : `resize-height-${fileIndex}-${optIndex}`;
        }
      }

      validOptions.push(opt);
    });

    return { isValid, validOptions, messages, firstInvalidInputId };
  };

  return (
    <Container>
      <div id="page-wrapper">
        <main id="main-content">
          {/* 상단 설명을 포함한 섹션 */}
          <HeaderSection
            style={{
              display: "flex",
              flexWrap: "nowrap",
              flexDirection: "column",
            }}
          >
            <h1>Convert and Resize Images to WEBP</h1>
            <p
              style={{
                padding: "20px 0 0 0",
                fontSize: "1.25rem",
                margin: "0",
              }}
            >
              Easily convert your images to the WebP format with optimized file
              size and quality. Add multiple resize options, maintain aspect
              ratio, and download everything as a ZIP file. Perfect for creating
              various image sizes for web, mobile, and apps—all in one place.
            </p>
            <p
              style={{
                fontSize: "1.25rem",
              }}
            >
              Use this tool to quickly convert image files to WebP format!
            </p>
            <Form.Group className="my-5 d-flex">
              <Form.Label htmlFor="file-upload" className="visually-hidden">
                Select image files to convert
              </Form.Label>

              <Form.Control
                id="file-upload"
                type="file"
                accept="image/jpeg, image/png"
                onChange={handleFileChange}
                multiple
                style={{
                  height: "80px",
                  lineHeight: "80px",
                  padding: "0 10px",
                  flex: "7",
                }}
              />
            </Form.Group>
          </HeaderSection>

          {/* 파일 선택 및 변환 영역 */}
          <Row className="justify-content-center mt-3 result-list">
            <Col md={10}>
              {files.length > 0 && (
                <Row className="justify-content-between align-items-center mb-3">
                  <Col md={6}>
                    <h3 className="text-start">Selected Images</h3>
                  </Col>
                  <Col md={6} className="text-end">
                    <Button
                      variant={allConverted ? "warning" : "danger"}
                      onClick={
                        allConverted ? handleDownloadAll : handleConvertAll
                      }
                      className="d-flex align-items-center"
                      style={{
                        justifyContent: "center",
                        fontWeight: "bold",
                        fontSize: "1.2rem",
                        padding: "10px 20px",
                        marginTop: "1rem",
                        width: "100%",
                      }}
                    >
                      {allConverted ? (
                        <>
                          <Download className="me-2" /> Download All
                        </>
                      ) : (
                        <>
                          <ArrowRepeat className="me-2" /> Convert All
                        </>
                      )}
                    </Button>
                  </Col>
                </Row>
              )}

              {isConverting && (
                <Row className="justify-content-center">
                  <Col md={6} className="text-center">
                    <div style={{ fontWeight: "bold", marginBottom: "5px" }}>
                      Converting... {conversionProgress}%
                    </div>
                    <div
                      style={{
                        height: "10px",
                        background: "#ddd",
                        borderRadius: "5px",
                      }}
                    >
                      <div
                        style={{
                          width: `${conversionProgress}%`,
                          height: "10px",
                          background: "#28a745",
                          borderRadius: "5px",
                          transition: "width 0.3s ease-in-out",
                        }}
                      ></div>
                    </div>
                  </Col>
                </Row>
              )}

              {files.map((file, index) => (
                <Row
                  key={index}
                  className="my-4 align-items-center p-3"
                  style={{
                    boxShadow: "0 2px 5px rgba(0,0,0,0.1)",
                    borderBottom: "1px solid #ddd",
                    backgroundColor: "gainsboro",
                    borderRadius: "1vw",
                    padding: "0 2vh",
                  }}
                >
                  {/* 썸네일 Col */}
                  <Col md={2} className="text-center">
                    {imageInfos[index] && (
                      <img
                        src={imageInfos[index].previewUrl}
                        alt={`preview-${index}`}
                        style={{
                          width: "100%",
                          height: "auto",
                          borderRadius: "5px",
                          objectFit: "cover",
                          boxShadow: "0 0 5px rgba(0,0,0,0.2)",
                        }}
                      />
                    )}
                  </Col>

                  <Col md={8}>
                    <h5
                      style={{
                        whiteSpace: "nowrap",
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                        width: "100%",
                        paddingBottom: "0.5rem",
                      }}
                    >
                      {file.name}
                    </h5>
                    {imageInfos[index] && (
                      <>
                        <div style={{ fontSize: "0.9rem", color: "#555" }}>
                          {imageInfos[index].width} × {imageInfos[index].height}
                          px / {(imageInfos[index].size / 1024).toFixed(1)} KB
                        </div>
                        {webpImageInfos[index]?.map((info, subIndex) => (
                          <div
                            key={subIndex}
                            style={{ fontSize: "0.9rem", color: "#006400" }}
                          >
                            {info?.size
                              ? `→ WebP #${subIndex + 1}: ${(
                                  info.size / 1024
                                ).toFixed(1)} KB`
                              : ""}
                          </div>
                        ))}

                        {resizeOptions[index]?.map((option, optionIndex) => (
                          <div
                            key={optionIndex}
                            className="option-style d-flex align-items-center gap-2 my-2"
                          >
                            <div className="option-wrapper">
                              <div
                                style={{
                                  width: "40px",
                                  fontWeight: "bold",
                                  color: "#333",
                                }}
                              >
                                #{optionIndex + 1}
                              </div>

                              <Form.Control
                                type="number"
                                min={1}
                                placeholder="Width"
                                id={`resize-width-${index}-${optionIndex}`}
                                value={option.width || ""}
                                onChange={(e) =>
                                  handleResizeInputChange(
                                    index,
                                    optionIndex,
                                    "width",
                                    e.target.value
                                  )
                                }
                                style={{ width: "100px" }}
                                isInvalid={!option.width}
                              />

                              <Form.Control
                                type="number"
                                min={1}
                                placeholder="Height"
                                id={`resize-height-${index}-${optionIndex}`}
                                value={
                                  option.maintainRatio &&
                                  option.width &&
                                  imageInfos[index]?.width > 0
                                    ? Math.round(
                                        (imageInfos[index].height /
                                          imageInfos[index].width) *
                                          parseInt(option.width)
                                      )
                                    : option.height || ""
                                }
                                onChange={(e) =>
                                  handleResizeInputChange(
                                    index,
                                    optionIndex,
                                    "height",
                                    e.target.value
                                  )
                                }
                                style={{ width: "100px" }}
                                disabled={option.maintainRatio}
                              />
                            </div>
                            <div className="option-wrapper">
                              <Form.Check
                                type="checkbox"
                                label="Maintain Ratio"
                                checked={option.maintainRatio || false}
                                onChange={(e) =>
                                  handleResizeInputChange(
                                    index,
                                    optionIndex,
                                    "maintainRatio",
                                    e.target.checked
                                  )
                                }
                              />

                              <Button
                                variant="outline-danger"
                                size="sm"
                                onClick={() =>
                                  handleRemoveResizeOption(index, optionIndex)
                                }
                              >
                                ❌
                              </Button>
                            </div>
                          </div>
                        ))}

                        {!webpUrls[index] && (
                          <Button
                            variant="outline-primary"
                            size="sm"
                            className="mb-3"
                            onClick={() => handleAddResizeOption(index)}
                          >
                            ➕ Add Resize Option
                          </Button>
                        )}
                      </>
                    )}
                  </Col>

                  <Col md={2} className="d-flex justify-content-end">
                    {webpUrls[index] ? (
                      <Button
                        variant="warning"
                        onClick={() => handleDownloadOne(index)}
                        className="d-flex align-items-center btn-fs"
                        style={{
                          justifyContent: "center",
                          width: "100%",
                          fontWeight: "bold",
                          padding: "10px",
                        }}
                      >
                        Download ZIP
                      </Button>
                    ) : (
                      <Button
                        variant="danger"
                        onClick={() => handleConvert(index)}
                        className="d-flex align-items-center btn-fs"
                        style={{
                          justifyContent: "center",
                          width: "100%",
                          fontWeight: "bold",
                          padding: "10px",
                        }}
                      >
                        Convert
                      </Button>
                    )}
                  </Col>
                </Row>
              ))}
            </Col>
          </Row>
          <ToastContainer position="top-center" autoClose={3000} />
        </main>
        <footer id="footer-ad">
          <ins
            style={{ display: "block", height: "60px" }}
            data-ad-client="ca-pub-4331956626091866"
            data-ad-slot="2609750493"
            data-ad-format="horizontal"
            data-full-width-responsive="false"
          />
          <script>(adsbygoogle = window.adsbygoogle || []).push({});</script>
        </footer>
      </div>
    </Container>
  );
}

export default App;
